  1	/* ============================================================
  2	   views/config-persona-models.js — Persona Models tab module
  3	   Section 4d-pm of the MCP Server Dashboard SPA
  4	   Depends on: API, UI, escapeHtml, configDirty (defined in config.js)
  5	   Must be loaded BEFORE config.js.
  6	   ============================================================ */
  7	
  8	/* ── Module-level state ──────────────────────────────────── */
  9	
 10	/* Module-level state for Persona Models tab.
 11	   pmModels:       working copy of model list (loaded from server, used for dropdowns).
 12	   pmPersonas:     full persona list from GET /api/personas.
 13	   pmAssignments:  working copy of assignments (default_model_uuid + persona_models).
 14	   pmOriginal:     snapshot of assignments at load/save time for dirty comparison.
 15	   pmIsBuilding:   true while a rebuild is in progress.
 16	   pmCollapsed:    set of suite names the user has collapsed.
 17	   pmReplaceOpen:  true when the Replace Model inline form is shown. */
 18	var pmModels      = null;   /* ModelEntry[] | null */
 19	var pmPersonas    = null;   /* PersonaEntry[] | null */
 20	var pmAssignments = null;   /* { default_model_uuid?: string, persona_models: {} } | null */
 21	var pmOriginal    = null;   /* deep-cloned snapshot for dirty comparison */
 22	var pmIsBuilding  = false;
 23	var pmCollapsed   = {};     /* { [suiteName]: boolean } */
 24	var pmReplaceOpen = false;
 25	
 26	/* Suite display labels — maps raw suite keys to user-facing strings. */
 27	var PM_SUITE_LABELS = {
 28	  'ledger':         'Ledger',
 29	  'standalone':     'Standalone',
 30	  'ledger-support': 'Ledger Support'
 31	};
 32	
 33	/* Ordered suite list for consistent rendering. */
 34	var PM_SUITE_ORDER = ['ledger', 'standalone', 'ledger-support'];
 35	
 36	/* ── Helpers ─────────────────────────────────────────────── */
 37	
 38	/** Deep-clone assignments object. */
 39	function pmCloneAssignments(a) {
 40	  if (!a) return { persona_models: {} };
 41	  return {
 42	    default_model_uuid: a.default_model_uuid,
 43	    persona_models: Object.assign({}, a.persona_models || {})
 44	  };
 45	}
 46	
 47	/** Return true when working copy has unsaved changes vs snapshot. */
 48	function pmHasChanges() {
 49	  if (!pmAssignments || !pmOriginal) return false;
 50	  if (pmAssignments.default_model_uuid !== pmOriginal.default_model_uuid) return true;
 51	  var aPm = pmAssignments.persona_models || {};
 52	  var oPm = pmOriginal.persona_models || {};
 53	  var aKeys = Object.keys(aPm);
 54	  var oKeys = Object.keys(oPm);
 55	  if (aKeys.length !== oKeys.length) return true;
 56	  for (var i = 0; i < aKeys.length; i++) {
 57	    if (aPm[aKeys[i]] !== oPm[aKeys[i]]) return true;
 58	  }
 59	  return false;
 60	}
 61	
 62	/** Resolve a model UUID to its display name. Returns null when not found. */
 63	function pmModelName(uuid) {
 64	  if (!uuid || !pmModels) return null;
 65	  for (var i = 0; i < pmModels.length; i++) {
 66	    if (pmModels[i].id === uuid) return pmModels[i].name;
 67	  }
 68	  return null;
 69	}
 70	
 71	/** Render a dirty indicator dot. */
 72	function pmDirtyDot(isDirty) {
 73	  return isDirty ? '<span class="pm-dirty-dot" title="Unsaved change"></span>' : '';
 74	}
 75	
 76	/** Build <option> elements for a model dropdown.
 77	 *  If includeDefault is true, prepends a "Default" option with value ''. */
 78	function pmBuildModelOptions(selectedUuid, includeDefault) {
 79	  var opts = '';
 80	  if (includeDefault) {
 81	    opts += '<option value=""' + (!selectedUuid ? ' selected' : '') + '>Default</option>';
 82	  }
 83	  if (pmModels) {
 84	    for (var i = 0; i < pmModels.length; i++) {
 85	      var m = pmModels[i];
 86	      var sel = (m.id === selectedUuid) ? ' selected' : '';
 87	      opts += '<option value="' + escapeHtml(m.id) + '"' + sel + '>' + escapeHtml(m.name) + '</option>';
 88	    }
 89	  }
 90	  return opts;
 91	}
